def character_replacement(s, k):
    n = len(s)
    best = 0
    for start in range(n):
        count = {}
        max_count = 0
        for end in range(start, n):
            count[s[end]] = count.get(s[end], 0) + 1                    # extend the window by one character
            max_count = max(max_count, count[s[end]])
            length = end - start + 1
            if length - max_count <= k:                                   # replacements needed fit within the budget k
                best = max(best, length)
    return best


if __name__ == "__main__":
    print(character_replacement("ABAB", 2))

