import java.util.*;

public class Main {
    int characterReplacement(String s, int k) {
        int n = s.length();
        int best = 0;
        for (int start = 0; start < n; start++) {
            Map<Character, Integer> count = new HashMap<>();
            int maxCount = 0;
            for (int end = start; end < n; end++) {
                count.merge(s.charAt(end), 1, Integer::sum);                    // extend the window by one character
                maxCount = Math.max(maxCount, count.get(s.charAt(end)));
                int length = end - start + 1;
                if (length - maxCount <= k) {                                     // replacements needed fit within the budget k
                    best = Math.max(best, length);
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.characterReplacement("ABAB", 2));
    }
}

