        unordered_map<char,int> count;
        int maxCount = 0;
        for (int end = start; end < n; end++) {
            count[s[end]]++;                                                   // extend the window by one character
            maxCount = max(maxCount, count[s[end]]);
            int length = end - start + 1;
            if (length - maxCount <= k) {                                        // replacements needed fit within the budget k
                best = max(best, length);
            }
        }
    }
    return best;
}

